/* Wubby's World: painterly conifer/birch sprites (cleaned alpha edges).
   Drop-in replacement for forest-painted-tree-art.js.
   Fix: decontaminated semi-transparent edge pixels to remove grey fringe, especially around roots. */
(()=>{'use strict';
const img=new Image();
let paintedAtlas=img;
const api={ready:false,source:'cleaned painted forest sprite study',draw(ctx,kind,variant,x,y,scale){
 if(!api.ready)return false;
 const family=kind==='birch'?2:0;const slot=family+(variant%2+2)%2;
 const width=90*scale*.72,height=130*scale;
 ctx.drawImage(paintedAtlas,slot*90,0,90,130,x-width/2,y-height,width,height);return true;
}};
window.WUBBY_PAINTED_FOREST_ART=api;
img.onload=()=>{
 // Remove grey source-sheet residue near the pines' roots while retaining the
 // clean, painterly anti-aliased tree edges and original tree proportions.
 const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;
 const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(img,0,0);
 const pixels=g.getImageData(0,0,c.width,c.height),v=pixels.data;
 const clamp=t=>Math.max(0,Math.min(1,t));
 for(let y=0;y<Math.min(130,c.height);y++)for(let x=0;x<Math.min(180,c.width);x++){
  const i=(y*c.width+x)*4,r=v[i],green=v[i+1],b=v[i+2];
  // Slightly desaturated pale ground is a leftover matte, not foliage or bark.
  const neutral=clamp((b/(green+1)-.61)/.18)*clamp((r-68)/35)*clamp((green-88)/30)*clamp((y-77)/18);
  let alpha=1-.94*neutral;
  const localX=x%90,cx=(x<90?.52:.50)*90;
  const t=clamp((y-100)/30);
  if(y>100){
   const radius=90*(.66*Math.pow(1-t,1.4)+.13);
   alpha*=clamp((radius+3-Math.abs(localX-cx))/6);
  }
  v[i+3]=Math.round(v[i+3]*alpha);
 }
 g.putImageData(pixels,0,0);paintedAtlas=c;
 api.ready=true;window.dispatchEvent(new Event('wubby-painted-forest-ready'));
};
img.src='data:image/png;base64,';
})();